import * as os from 'node:os';
import * as path from 'node:path';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import type { Config } from '../../config/config.js';

/**
 * The pinned version of the `chrome-devtools-mcp` package that the browser
 * agent launches via `npx`.
 */
export const CHROME_DEVTOOLS_MCP_VERSION = '0.6.0';

/**
 * The name of the directory used for the persistent browser profile. The full
 * path lives inside the user's home directory.
 */
export const BROWSER_PROFILE_DIR_NAME = 'cli-browser-profile';

/**
 * A tool discovered from the connected MCP server.
 */
export interface McpTool {
  name: string;
  description?: string;
  inputSchema: unknown;
}

/**
 * A single content item returned from an MCP tool call.
 */
export interface McpContentItem {
  type: 'text' | 'image';
  text?: string;
  data?: string;
  mimeType?: string;
}

/**
 * The normalized result of an MCP tool call.
 */
export interface McpToolCallResult {
  content?: McpContentItem[];
  isError?: boolean;
}

/**
 * Manages the lifecycle of a browser instance driven through the
 * `chrome-devtools-mcp` server. It owns a raw MCP SDK {@link Client} that talks
 * to a `npx`-spawned Chrome DevTools MCP process over stdio.
 *
 * This deliberately does NOT go through the shared `McpClientManager`; the
 * browser agent maintains its own isolated connection.
 */
export class BrowserManager {
  private client: Client | undefined;
  private connected = false;
  private discoveredTools: McpTool[] | undefined;

  constructor(private readonly config: Config) {}

  /**
   * Returns the raw MCP SDK client, creating it lazily. Subsequent calls return
   * the same cached instance without constructing a new {@link Client}.
   */
  async getRawMcpClient(): Promise<Client> {
    if (!this.client) {
      this.client = new Client({
        name: 'gemini-cli-browser-agent',
        version: CHROME_DEVTOOLS_MCP_VERSION,
      });
    }
    return this.client;
  }

  /**
   * Builds the `npx` argument list used to launch `chrome-devtools-mcp` based
   * on the resolved browser agent configuration.
   */
  private buildArgs(): string[] {
    const { customConfig } = this.config.getBrowserAgentConfig();
    const sessionMode = customConfig.sessionMode ?? 'persistent';

    const args: string[] = [
      '-y',
      `chrome-devtools-mcp@${CHROME_DEVTOOLS_MCP_VERSION}`,
      '--experimental-vision',
    ];

    if (customConfig.headless) {
      args.push('--headless');
    }

    if (sessionMode === 'isolated') {
      args.push('--isolated');
    } else if (sessionMode === 'existing') {
      args.push('--autoConnect');
    } else {
      // Persistent mode (the default): reuse a dedicated profile directory.
      const profilePath =
        customConfig.profilePath ??
        path.join(os.homedir(), '.gemini', BROWSER_PROFILE_DIR_NAME);
      args.push('--userDataDir', profilePath);
    }

    return args;
  }

  /**
   * Establishes the connection to the `chrome-devtools-mcp` server, spawning
   * the underlying Chrome instance. Safe to call multiple times; the connection
   * is only established once.
   */
  async ensureConnection(): Promise<void> {
    if (this.connected) {
      return;
    }

    const { customConfig } = this.config.getBrowserAgentConfig();
    const sessionMode = customConfig.sessionMode ?? 'persistent';

    const client = await this.getRawMcpClient();
    const transport = new StdioClientTransport({
      command: 'npx',
      args: this.buildArgs(),
    });

    try {
      await client.connect(transport);
      this.connected = true;
    } catch (error) {
      throw this.createConnectionError(sessionMode, error);
    }
  }

  /**
   * Maps a low-level connection failure onto an actionable, user-facing error
   * whose message depends on the configured session mode.
   */
  private createConnectionError(
    sessionMode: 'isolated' | 'persistent' | 'existing',
    error: unknown,
  ): Error {
    const message = error instanceof Error ? error.message : String(error);
    const lower = message.toLowerCase();

    if (sessionMode === 'existing') {
      return new Error(
        'Failed to connect to existing Chrome instance. ' +
          'Make sure Chrome is running with remote debugging enabled. ' +
          'You can inspect available targets at chrome://inspect/#remote-debugging.\n' +
          `Underlying error: ${message}`,
      );
    }

    if (sessionMode === 'isolated') {
      return new Error(
        `Failed to start an isolated Chrome instance for the browser agent.\n` +
          `Underlying error: ${message}`,
      );
    }

    // Persistent mode.
    if (lower.includes('already running') || lower.includes('already in use')) {
      return new Error(
        'Failed to start Chrome for the browser agent because the profile is ' +
          'already running. Close all Chrome windows using this profile and try ' +
          'again, or set sessionMode to "isolated" to use a separate profile.\n' +
          `Underlying error: ${message}`,
      );
    }

    if (lower.includes('timeout') || lower.includes('timed out')) {
      return new Error(
        'Timed out starting Chrome for the browser agent. Chrome is not ' +
          'installed or could not be launched. Please ensure Google Chrome is ' +
          'installed and available.\n' +
          `Underlying error: ${message}`,
      );
    }

    return new Error(
      'Failed to start the browser agent (sessionMode: persistent).\n' +
        `Underlying error: ${message}`,
    );
  }

  /**
   * Returns the tools exposed by the connected MCP server.
   */
  async getDiscoveredTools(): Promise<McpTool[]> {
    if (this.discoveredTools) {
      return this.discoveredTools;
    }
    await this.ensureConnection();
    const client = await this.getRawMcpClient();
    const response = await client.listTools();
    this.discoveredTools = (response.tools ?? []).map((tool) => ({
      name: tool.name,
      description: tool.description,
      inputSchema: tool.inputSchema,
    }));
    return this.discoveredTools;
  }

  /**
   * Calls a tool on the connected MCP server, normalizing the raw SDK response
   * into an {@link McpToolCallResult}.
   */
  async callTool(
    toolName: string,
    args: Record<string, unknown>,
    signal?: AbortSignal,
  ): Promise<McpToolCallResult> {
    await this.ensureConnection();
    const client = await this.getRawMcpClient();
    const raw = await client.callTool(
      { name: toolName, arguments: args },
      undefined,
      signal ? { signal } : undefined,
    );

    const content = Array.isArray(raw?.['content'])
      ? // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        (raw['content'] as McpContentItem[])
      : [];

    return {
      content,
      isError: raw?.['isError'] === true,
    };
  }

  /**
   * Closes the MCP client connection, releasing the underlying Chrome instance.
   */
  async close(): Promise<void> {
    if (this.client) {
      await this.client.close();
    }
    this.client = undefined;
    this.connected = false;
    this.discoveredTools = undefined;
  }
}
