import type {
  PolicyUpdateOptions,
  ToolCallConfirmationDetails,
  ToolInvocation,
  ToolMcpConfirmationDetails,
  ToolResult,
} from '../../tools/tools.js';
import {
  BaseDeclarativeTool,
  BaseToolInvocation,
  Kind,
  ToolConfirmationOutcome,
} from '../../tools/tools.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import type {
  BrowserManager,
  McpContentItem,
  McpToolCallResult,
} from './browserManager.js';

/**
 * The synthetic MCP server name used for policy checks and confirmation UI for
 * every tool the browser agent exposes.
 */
export const BROWSER_MCP_SERVER_NAME = 'browser-agent';

/**
 * The name of the composite text-entry tool that is always added on top of the
 * discovered MCP tools.
 */
export const TYPE_TEXT_TOOL_NAME = 'type_text';

const TYPE_TEXT_DESCRIPTION =
  'Type text into the element identified by `uid`. This is a convenience tool ' +
  'that focuses the target element and enters the provided text, optionally ' +
  'submitting it afterwards.';

const TYPE_TEXT_SCHEMA = {
  type: 'object',
  properties: {
    uid: {
      type: 'string',
      description: 'The uid of the element to type into.',
    },
    text: {
      type: 'string',
      description: 'The text to type.',
    },
    submit: {
      type: 'boolean',
      description: 'Whether to submit the form after typing (press Enter).',
    },
  },
  required: ['uid', 'text'],
};

type ToolParams = Record<string, unknown>;

/**
 * Extracts and concatenates the text content from an MCP tool call result.
 */
function extractTextContent(content: McpContentItem[] | undefined): string {
  if (!content) {
    return '';
  }
  return content
    .filter((item) => item.type === 'text' && typeof item.text === 'string')
    .map((item) => item.text)
    .join('\n');
}

/**
 * An executable invocation for a single browser MCP tool. It forwards the call
 * to the {@link BrowserManager} and normalizes the result into a
 * {@link ToolResult}.
 */
class BrowserMcpToolInvocation extends BaseToolInvocation<
  ToolParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    messageBus: MessageBus,
    private readonly mcpToolName: string,
    private readonly toolDescription: string,
    private readonly toolParameterSchema: unknown,
    params: ToolParams,
  ) {
    super(
      params,
      messageBus,
      mcpToolName,
      mcpToolName,
      BROWSER_MCP_SERVER_NAME,
    );
  }

  getDescription(): string {
    return `${this.mcpToolName}(${JSON.stringify(this.params)})`;
  }

  protected override getPolicyUpdateOptions(
    _outcome: ToolConfirmationOutcome,
  ): PolicyUpdateOptions | undefined {
    return { mcpName: BROWSER_MCP_SERVER_NAME };
  }

  protected override async getConfirmationDetails(
    _abortSignal: AbortSignal,
  ): Promise<ToolCallConfirmationDetails | false> {
    const confirmationDetails: ToolMcpConfirmationDetails = {
      type: 'mcp',
      title: 'Confirm Browser Agent Tool Execution',
      serverName: BROWSER_MCP_SERVER_NAME,
      toolName: this.mcpToolName,
      toolDisplayName: this.mcpToolName,
      toolArgs: this.params,
      toolDescription: this.toolDescription,
      toolParameterSchema: this.toolParameterSchema,
      onConfirm: async (outcome: ToolConfirmationOutcome) => {
        await this.publishPolicyUpdate(outcome);
      },
    };
    return confirmationDetails;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    let result: McpToolCallResult;
    try {
      result = await this.browserManager.callTool(
        this.mcpToolName,
        this.params,
        signal,
      );
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      return {
        llmContent: `Error: ${errorMsg}`,
        returnDisplay: `Error: ${errorMsg}`,
        error: { message: errorMsg },
      };
    }

    const textContent = extractTextContent(result.content);

    if (result.isError) {
      return {
        llmContent: `Error: ${textContent}`,
        returnDisplay: `Error: ${textContent}`,
        error: { message: textContent },
      };
    }

    return {
      llmContent: textContent,
      returnDisplay: textContent,
      error: undefined,
    };
  }
}

/**
 * A declarative tool that wraps a single browser MCP tool (or the composite
 * `type_text` tool).
 */
class BrowserMcpTool extends BaseDeclarativeTool<ToolParams, ToolResult> {
  constructor(
    private readonly browserManager: BrowserManager,
    messageBus: MessageBus,
    name: string,
    description: string,
    parameterSchema: unknown,
  ) {
    super(
      name,
      name,
      description,
      Kind.Other,
      parameterSchema,
      messageBus,
      /* isOutputMarkdown */ true,
      /* canUpdateOutput */ false,
    );
  }

  protected createInvocation(
    params: ToolParams,
    messageBus: MessageBus,
  ): ToolInvocation<ToolParams, ToolResult> {
    return new BrowserMcpToolInvocation(
      this.browserManager,
      messageBus,
      this.name,
      this.description,
      this.parameterSchema,
      params,
    );
  }
}

/**
 * Discovers the MCP tools exposed by the browser manager and wraps each one as
 * a {@link BaseDeclarativeTool}. A composite `type_text` tool is always added
 * on top of the discovered tools.
 */
export async function createMcpDeclarativeTools(
  browserManager: BrowserManager,
  messageBus: MessageBus,
): Promise<Array<BaseDeclarativeTool<ToolParams, ToolResult>>> {
  const discovered = await browserManager.getDiscoveredTools();

  const tools: Array<BaseDeclarativeTool<ToolParams, ToolResult>> =
    discovered.map(
      (tool) =>
        new BrowserMcpTool(
          browserManager,
          messageBus,
          tool.name,
          tool.description ?? '',
          tool.inputSchema,
        ),
    );

  tools.push(
    new BrowserMcpTool(
      browserManager,
      messageBus,
      TYPE_TEXT_TOOL_NAME,
      TYPE_TEXT_DESCRIPTION,
      TYPE_TEXT_SCHEMA,
    ),
  );

  return tools;
}
