import { z } from 'zod';
import type { Config } from '../../config/config.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import type { AnyDeclarativeTool } from '../../tools/tools.js';
import { DEFAULT_GEMINI_MODEL } from '../../config/models.js';
import type { LocalAgentDefinition } from '../types.js';
import { BrowserManager } from './browserManager.js';
import { createMcpDeclarativeTools } from './mcpToolWrapper.js';
import { createAnalyzeScreenshotTool } from './analyzeScreenshot.js';
import {
  BROWSER_AGENT_NAME,
  buildBrowserSystemPrompt,
} from './browserAgentDefinition.js';

const BrowserAgentOutputSchema = z.object({
  result: z
    .string()
    .describe('A summary of what the browser agent did and the outcome.'),
});

/**
 * Creates the browser agent definition along with the {@link BrowserManager}
 * that backs it.
 *
 * This establishes the browser connection, discovers the MCP tools, wraps them
 * as declarative tools, and conditionally adds the `analyze_screenshot` tool
 * when a visual model is configured.
 *
 * @param config The runtime configuration.
 * @param messageBus The message bus used for tool policy enforcement.
 * @param printOutput Optional callback used to surface progress to the user.
 */
export async function createBrowserAgentDefinition(
  config: Config,
  messageBus: MessageBus,
  printOutput?: (msg: string) => void,
): Promise<{
  definition: LocalAgentDefinition<typeof BrowserAgentOutputSchema>;
  browserManager: BrowserManager;
}> {
  const browserAgentConfig = config.getBrowserAgentConfig();
  const visionEnabled = !!browserAgentConfig.customConfig.visualModel;

  const browserManager = new BrowserManager(config);
  await browserManager.ensureConnection();

  if (printOutput) {
    printOutput('Browser agent connected to Chrome.');
  }

  const tools: AnyDeclarativeTool[] = await createMcpDeclarativeTools(
    browserManager,
    messageBus,
  );

  if (visionEnabled) {
    tools.push(createAnalyzeScreenshotTool(browserManager, config, messageBus));
  }

  const definition: LocalAgentDefinition<typeof BrowserAgentOutputSchema> = {
    kind: 'local',
    name: BROWSER_AGENT_NAME,
    displayName: 'Browser Agent',
    description:
      'An autonomous agent that drives a real Chrome browser to accomplish ' +
      'web-based tasks such as navigation, form filling, and data extraction.',
    experimental: true,
    inputConfig: {
      inputSchema: {
        type: 'object',
        properties: {
          task: {
            type: 'string',
            description: 'The web-based task for the browser agent to perform.',
          },
        },
        required: ['task'],
      },
    },
    outputConfig: {
      outputName: 'result',
      description: 'A summary of what the browser agent did and the outcome.',
      schema: BrowserAgentOutputSchema,
    },
    modelConfig: {
      model: browserAgentConfig.model ?? DEFAULT_GEMINI_MODEL,
    },
    runConfig: {
      maxTimeMinutes: 10,
      maxTurns: 25,
    },
    toolConfig: {
      tools,
    },
    promptConfig: {
      systemPrompt: buildBrowserSystemPrompt(visionEnabled),
      query: '${task}',
    },
  };

  return { definition, browserManager };
}

/**
 * Cleans up the browser agent by closing the browser manager. Resolves even if
 * closing throws, so callers can safely use it in a `finally` block.
 */
export async function cleanupBrowserAgent(
  browserManager: BrowserManager,
): Promise<void> {
  try {
    await browserManager.close();
  } catch {
    // Ignore errors during cleanup; the browser process will be reaped anyway.
  }
}
