/**
 * The name of the visual analysis tool.
 */
export const ANALYZE_SCREENSHOT_TOOL_NAME = 'analyze_screenshot';

/**
 * The MCP tool used to capture a screenshot of the current page.
 */
const SCREENSHOT_TOOL_NAME = 'take_screenshot';

interface AnalyzeScreenshotParams {
  instruction: string;
}

/**
 * Finds the first image content item in an MCP tool call result.
 */
function findImageContent(
  content: McpContentItem[] | undefined,
): McpContentItem | undefined {
  return content?.find(
    (item) => item.type === 'image' && typeof item.data === 'string',
  );
}

class AnalyzeScreenshotInvocation extends BaseToolInvocation<
  AnalyzeScreenshotParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    messageBus: MessageBus,
    params: AnalyzeScreenshotParams,
  ) {
    super(params, messageBus, ANALYZE_SCREENSHOT_TOOL_NAME, 'Analyze Screenshot');
  }

  getDescription(): string {
    return `Analyze a screenshot of the current page: ${this.params.instruction}`;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    // 1. Capture a screenshot of the current page.
    const screenshot = await this.browserManager.callTool(
      SCREENSHOT_TOOL_NAME,
      {},
      signal,
    );

    const image = findImageContent(screenshot.content);
    if (!image) {
      const message =
        'Failed to capture screenshot: no image content was returned by the browser.';
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message },
      };
    }

    // 2. Send the screenshot to the visual model for analysis.
    const model =
      this.config.getBrowserAgentConfig().customConfig.visualModel ??
      DEFAULT_GEMINI_MODEL;

    let response: GenerateContentResponse;
    try {
      response = await this.config.getContentGenerator().generateContent(
        {
          model,
          contents: [
            {
              role: 'user',
              parts: [
                { text: this.params.instruction },
                {
                  inlineData: {
                    mimeType: image.mimeType ?? 'image/png',
                    data: image.data ?? '',
                  },
                },
              ],
            },
          ],
        },
        'browser-agent-analyze-screenshot',
        LlmRole.UTILITY_TOOL,
      );
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      const lower = errorMsg.toLowerCase();
      if (
        lower.includes('404') ||
        lower.includes('403') ||
        lower.includes('not found') ||
        lower.includes('permission')
      ) {
        const message =
          'Visual analysis model is not available. The configured visual model ' +
          `could not be reached (${errorMsg}).`;
        return {
          llmContent: message,
          returnDisplay: message,
          error: { message },
        };
      }
      const message = `Visual analysis failed: ${errorMsg}`;
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message },
      };
    }

    const parts = response?.candidates?.[0]?.content?.parts;
    const text = getResponseText(response);
    if (!parts || parts.length === 0 || !text) {
      const message = 'Visual model returned no analysis.';
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message },
      };
    }

    const content = `Visual Analysis Result:\n\n${text}`;
    return {
      llmContent: content,
      returnDisplay: content,
      error: undefined,
    };
  }
}

